(()=>{'use strict';const panel=$('#now-playing'),message=$('#np-message');let sleepTimer;
const icon=name=>`<span class="material-symbols-rounded" aria-hidden="true">${name}</span>`;
function sync(){const t=tracks[current];if(!t)return;$('#np-title').textContent=t.title;$('#np-artist').textContent=t.artist;$('#np-artist').disabled=!t.artistId;if(t.artwork){if($('#np-art').getAttribute('src')!==t.artwork)$('#np-art').src=t.artwork}else $('#np-art').removeAttribute('src');$('#np-art').hidden=!t.artwork;$('#np-art-fallback').hidden=!!t.artwork;$('#quality').textContent=(window.OktawkaStreaming?.pending||window.MonoAudioQuality.label(t));$('#np-quality').textContent=(window.OktawkaStreaming?.pending||window.MonoAudioQuality.label(t));$('#np-codec').textContent=t.quality?.channels>2?(t.quality.channels===6?'5.1 FLAC':t.quality.channels===8?'7.1 FLAC':t.quality.channels+'-channel FLAC'):'Stereo / source layout unverified';$('#np-play').innerHTML=icon(audio.paused?'play_arrow':'pause');$('#np-play').setAttribute('aria-label',audio.paused?'Play':'Pause');$('#np-like').innerHTML=icon(liked.has(current)?'favorite':'favorite_border');$('#np-like').setAttribute('aria-pressed',liked.has(current));$('#np-shuffle').setAttribute('aria-pressed',shuffle);$('#np-repeat').setAttribute('aria-pressed',audio.loop);$('#np-elapsed').textContent=time(audio.currentTime);$('#np-duration').textContent=t.live?'LIVE':time(audio.duration);$('#np-seek').disabled=!!t.live||audio.seekable===false;$('#np-seek').value=Number.isFinite(audio.duration)&&audio.duration?audio.currentTime/audio.duration*100:0;const path=audio.signalPath;$('#np-engine').textContent=(path?.decoder||'Browser native decoder')+(path?.eq?' · EQ on':' · EQ bypassed');window.OktawkaLyrics?.sync(audio.currentTime,panel.open&&!document.hidden)}
function open(){if(current<0)return toast('Choose a track first.');sync();if(!panel.open)panel.showModal();window.OktawkaLyrics?.load(tracks[current],audio.duration)}
window.OktawkaOnTrack=t=>{message.textContent='';window.OktawkaLyrics?.reset(t);sync();if(panel.open)window.OktawkaLyrics?.load(t,audio.duration)};window.OktawkaOnPlaying=()=>{sync();window.OktawkaFlow?.remember(tracks[current])};
$('#expand-player').onclick=open;$('#mini-art').onclick=open;$('#np-close').onclick=()=>panel.close();$('#np-play').onclick=()=>{toggle();sync()};$('#np-next').onclick=()=>next();$('#np-prev').onclick=()=>$('#prev').click();$('#np-like').onclick=()=>{$('#like').click();sync()};$('#np-shuffle').onclick=()=>{$('#shuffle').click();sync()};$('#np-repeat').onclick=()=>{$('#repeat').click();sync()};$('#np-seek').oninput=e=>{if(audio.seekable!==false&&Number.isFinite(audio.duration))audio.currentTime=audio.duration*e.target.value/100};$('#np-artist').onclick=()=>{const t=tracks[current];if(t.artistId){panel.close();window.monoOpenArtist?.(t.artistId,t.artist)}};
for(const type of ['play','pause','loadedmetadata','durationchange','qualitychange'])audio.addEventListener(type,sync);audio.addEventListener('loadedmetadata',()=>{if(panel.open)window.OktawkaLyrics?.load(tracks[current],audio.duration)});audio.addEventListener('timeupdate',()=>{if(panel.open&&!document.hidden)sync()});audio.addEventListener('error',()=>{message.textContent=audio.lastError||'Audio could not play. Retry another source or use the FLAC compatibility decoder.'});
$('#np-share').onclick=async()=>{const t=tracks[current];if(!t)return;const data={title:t.title,text:t.title+' — '+t.artist};try{if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(data.text);message.textContent='Track details copied.'}}catch{message.textContent='Sharing was cancelled or unavailable.'}};
$('#np-quality').onclick=()=>{panel.close();details()};$('#np-queue').onclick=()=>{panel.close();$('#queue').click()};$('#np-eq').onclick=()=>{panel.close();equalizer()};$('#np-info').onclick=()=>{panel.close();details()};
function details(){const t=tracks[current],q=t?.quality,path=audio.signalPath;modal(`<div class="eyebrow">THE SIGNAL PATH</div><h2>Know what you’re hearing.</h2><div class="signal-grid"><p><b>Source</b><span>${escapeHTML(t?(window.OktawkaStreaming?.pending||window.MonoAudioQuality.label(t)):'No track selected')}</span></p><p><b>Provider quality</b><span>${escapeHTML(t?.reportedQuality?.bitDepth?String(t.reportedQuality.bitDepth)+'-bit / '+Number(t.reportedQuality.sampleRate)/1000+' kHz (reported, not verified)':'Not reported')}${t?.qualityFallback?' · preferred format unavailable; fallback selected':''}</span></p><p><b>Decoder</b><span>${escapeHTML(path?.decoder||'Native')}</span></p><p><b>Processing</b><span>${path?.eq?'31-band / parametric EQ active':'EQ bypassed'}</span></p><p><b>Web Audio output</b><span>${path?.outputRate?path.outputRate/1000+' kHz · device may resample':'Managed by browser and device'}</span></p></div><label for="decoder-mode">FLAC playback path</label><select id="decoder-mode"><option value="native">Native · recommended for battery life</option><option value="wasm">libFLAC WASM · compatibility decoder</option></select><p class="note">Compatibility mode decodes FLAC up to 24-bit in a worker, with a bounded audio queue. Requires fetch/CORS access. Seeking is disabled in this streaming path. Changing mode applies to the next playback.</p><h3>Spatial audio & Samsung</h3><p class="note">Stereo FLAC stays stereo. Multichannel FLAC source channels are shown when verified; the device may downmix. Dolby Atmos and Sony 360 decoding are not integrated. On compatible Samsung phones, enable Dolby Atmos in system sound settings for Samsung’s output processing. Oktawka cannot toggle or verify that setting, and this does not turn the source into an Atmos recording.</p><p class="note"><a href="/third-party-notices.txt" target="_blank" rel="noopener">Decoder & icon licenses</a> · <a href="/decoder-sources.tgz">Decoder source packages</a></p><label for="sleep-minutes">Sleep timer</label><select id="sleep-minutes"><option value="0">Off</option><option value="15">15 minutes</option><option value="30">30 minutes</option><option value="60">60 minutes</option></select><button id="apply-audio-path" class="primary">Save audio options</button>`);$('#decoder-mode').value=audio.preference||'native';$('#apply-audio-path').onclick=()=>{audio.preference=$('#decoder-mode').value;try{localStorage.setItem('oktawka-decoder',audio.preference)}catch{}clearTimeout(sleepTimer);const minutes=Number($('#sleep-minutes').value);if(minutes)sleepTimer=setTimeout(()=>{audio.pause();toast('Sleep timer finished.')},minutes*60000);$('#dialog').close();toast('Playback path saved'+(minutes?' · sleep in '+minutes+' minutes':''))}}
function equalizer(){if(!audio.enableEQ)return toast('Web Audio processing is unavailable.');modal(`<div class="eyebrow">SHAPE YOUR SOUND</div><h2>31 bands. Your balance.</h2><label class="row"><span>Enable EQ</span><input id="eq-enabled" type="checkbox"></label><p class="note">Off by default. EQ changes samples and uses extra processing; it is not bit-perfect output. Native remote audio needs CORS permission for Web Audio. Enabling EQ restarts the current source.</p><label for="eq-preamp">Preamp <output id="eq-preamp-value">${audio.preamp} dB</output></label><input id="eq-preamp" type="range" min="-24" max="0" step="1" value="${audio.preamp}"><div class="eq-bands">${window.OktawkaEngine.bands.map((f,i)=>`<label><output id="eq-value-${i}">${audio.eqGains[i]}</output><input type="range" data-eq-band="${i}" aria-label="${f} Hz gain" min="-12" max="12" step=".5" value="${audio.eqGains[i]}"><span>${f>=1000?f/1000+'k':f}</span></label>`).join('')}</div><h3>Parametric EQ</h3><div class="parametric">${audio.parametric.map((p,i)=>`<fieldset><legend>Band ${i+1}</legend><label>Hz<input type="number" data-param="${i}" data-field="frequency" min="20" max="20000" value="${p.frequency}"></label><label>Gain dB<input type="number" data-param="${i}" data-field="gain" min="-12" max="12" step=".5" value="${p.gain}"></label><label>Q<input type="number" data-param="${i}" data-field="Q" min=".1" max="20" step=".1" value="${p.Q}"></label></fieldset>`).join('')}</div><p id="eq-status" class="note" role="status">Use a negative preamp to leave headroom. Large boosts may still clip.</p><button id="eq-reset">Reset gains</button>`);$('#eq-enabled').checked=audio.eqEnabled;$('#eq-enabled').onchange=async e=>{try{await audio.enableEQ(e.target.checked);if(current>=0&&audio.mode==='native')await play(current,true);$('#eq-status').textContent=audio.eqEnabled?'EQ enabled. If a remote source is silent, its server may not allow Web Audio/CORS.':'EQ bypassed.'}catch(error){e.target.checked=false;$('#eq-status').textContent=error.message}};$('#eq-preamp').oninput=e=>{audio.preamp=Number(e.target.value);$('#eq-preamp-value').textContent=audio.preamp+' dB';audio.updateEQ()};$('#dialog-content').querySelectorAll('[data-eq-band]').forEach(input=>input.oninput=()=>{audio.eqGains[Number(input.dataset.eqBand)]=Number(input.value);$('#eq-value-'+input.dataset.eqBand).textContent=input.value;audio.updateEQ()});$('#dialog-content').querySelectorAll('[data-param]').forEach(input=>input.onchange=()=>{const ranges={frequency:[20,20000],gain:[-12,12],Q:[.1,20]},range=ranges[input.dataset.field];const value=Math.min(range[1],Math.max(range[0],Number(input.value)||range[0]));input.value=value;audio.parametric[Number(input.dataset.param)][input.dataset.field]=value;audio.updateEQ()});$('#eq-reset').onclick=()=>{audio.eqGains.fill(0);audio.parametric.forEach(p=>p.gain=0);audio.updateEQ();equalizer()}}
try{audio.preference=localStorage.getItem('oktawka-decoder')==='wasm'?'wasm':'native'}catch{}window.OktawkaAudioDetails=details;window.OktawkaEqualizer=equalizer;
})();
